            continue  # skip non-string entries

        arg = raw_arg.strip()
        if not arg:
            continue

        # Remove leading dashes
        if arg.startswith("--"):
            arg = arg[2:]
        elif arg.startswith("-"):
            arg = arg[1:]

        # Split key and value
        if "=" in arg:
            key, value = arg.split("=", 1)
        else:
            key, value = arg, True

